test_that("oracle metrics have expected long format", {s<-bench_fixture();z<-evaluate_metrics(s,oracle_result(s));expect_identical(names(z),c("study","scenario","replicate","method_id","trait","metric","value","status","reason"));expect_true(all(z$status=="ok"));expect_true(all(abs(z$value[z$metric!="prediction_correlation"])<1e-12));expect_true(all(abs(z$value[z$metric=="prediction_correlation"]-1)<1e-12))})
test_that("Brier is hand calculable and missing outputs skip", {s<-bench_fixture();p<-matrix(.5,3,2,dimnames=list(s$data$marker_ids,s$data$trait_names));z<-metric_pip_brier(s,new_sblrbench_result("x",pip=p));expect_equal(z$value,c(.25,.25));expect_true(all(metric_effect_rmse(s,new_sblrbench_result("x"))$status=="skipped"))})
test_that("metric mismatches and zero variance are explicit", {s<-bench_fixture();r<-oracle_result(s);rownames(r$estimates$effects)[1]<-"bad";expect_error(metric_effect_rmse(s,r),"Missing");r<-oracle_result(s);rownames(r$predictions$genetic_value)[1]<-"bad";expect_error(metric_prediction_mse(s,r),"Missing");r<-oracle_result(s);colnames(r$estimates$pip)[1]<-"bad";expect_error(metric_pip_brier(s,r),"Missing");r<-oracle_result(s);r$predictions$genetic_value[,]<-1;expect_true(all(metric_prediction_correlation(s,r)$status=="failed"))})
